    def parse_range_header(self, range_header: str, file_size: int) -> tuple[int, int]:
        if not range_header.startswith('bytes='):
            return 0, file_size - 1

        ranges = range_header[6:].split(',')
        if len(ranges) > 1:
            raise HTTPException(status_code=416, detail='Multiple ranges not supported')

        start, end = ranges[0].split('-')
        start = int(start) if start else 0
        end = int(end) if end else file_size - 1

        if start >= file_size or (end and end < start):
            raise HTTPException(status_code=416, detail='Invalid range')

        end = min(end, file_size - 1)
        return start, end
